This PR changed the inner variant classes in generated union shapes in trait codegen to public.
Given this model:
```smithy
@trait
@documentation("This is my union trait!!!")
union UnionTrait {
    @documentation("This is my union trait's unit variant!!!")
    unitVariant: Unit

    @idRef
    stringVariant: String

    @documentation("This is my union trait's integer variant!!!")
    integerVariant: Integer

    structVariant: Type

    unionVariant: NestedUnionA

    listVariant: StringListA

    setVariant: StringSetA

    mapVariant: StringStringMapA

    @timestampFormat("http-date")
    timestampVariant: Timestamp
}
```

 and the current generated code would be: 

```java 
@SmithyGenerated
public abstract class UnionTrait extends AbstractTrait {
    public static final ShapeId ID = ShapeId.from("test.smithy.traitcodegen.unions#UnionTrait");

    private final Type type;

    private UnionTrait(Type type, FromSourceLocation sourceLocation) {
        super(ID, sourceLocation);
        this.type = Objects.requireNonNull(type);
    }

    @Override
    protected Node createNode() {
        return Node.objectNodeBuilder().withMember(getTag(), asNode()).build();
    }

    public static UnionTrait fromNode(Node node) {
        Map<StringNode, Node> members = node.expectObjectNode().getMembers();
        if (members.size() != 1) {
            throw new IllegalArgumentException("Expected only one member for union node.");
        }
        Entry<StringNode, Node> value = members.entrySet().iterator().next();
        switch (value.getKey().getValue()) {
            case "unitVariant":
                return UnitVariantMember.from(value.getValue());
            case "stringVariant":
                return StringVariantMember.from(value.getValue());
            case "integerVariant":
                return IntegerVariantMember.from(value.getValue());
            case "structVariant":
                return StructVariantMember.from(value.getValue());
            case "unionVariant":
                return UnionVariantMember.from(value.getValue());
            case "listVariant":
                return ListVariantMember.from(value.getValue());
            case "setVariant":
                return SetVariantMember.from(value.getValue());
            case "mapVariant":
                return MapVariantMember.from(value.getValue());
            case "timestampVariant":
                return TimestampVariantMember.from(value.getValue());
            default:
                throw new IllegalArgumentException("Unknown union variant.");
        }
    }

    public String getTag() {
        return type.getValue();
    }

    public Type getType() {
        return type;
    }

    public enum Type {
        unitVariant("unitVariant"),
        stringVariant("stringVariant"),
        integerVariant("integerVariant"),
        structVariant("structVariant"),
        unionVariant("unionVariant"),
        listVariant("listVariant"),
        setVariant("setVariant"),
        mapVariant("mapVariant"),
        timestampVariant("timestampVariant");

        private final String value;

        Type(String value) {
            this.value = value;
        }

        public String getValue() {
            return this.value;
        }
    }

    abstract Node asNode();

    public abstract <T> T getValue();

  
    @SmithyGenerated
    public static final class StringVariantMember extends UnionTrait {
        private final ShapeId value;

        private StringVariantMember(ShapeId value) {
            this(value, SourceLocation.NONE);
        }

        private StringVariantMember(ShapeId value, FromSourceLocation sourceLocation) {
            super(Type.stringVariant, sourceLocation);
            this.value = Objects.requireNonNull(value);
        }

        private static StringVariantMember from(Node node) {
            return new StringVariantMember(ShapeId.fromNode(node));
        }

        @Override
        Node asNode() {
            return Node.from(value.toString());
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T getValue() {
            return (T) value;
        }
    }

    /**
     * This is my union trait's integer variant!!!
     */
    @SmithyGenerated
    public static final class IntegerVariantMember extends UnionTrait {
        private final Integer value;

        private IntegerVariantMember(Integer value) {
            this(value, SourceLocation.NONE);
        }

        private IntegerVariantMember(Integer value, FromSourceLocation sourceLocation) {
            super(Type.integerVariant, sourceLocation);
            this.value = Objects.requireNonNull(value);
        }

        private static IntegerVariantMember from(Node node) {
            return new IntegerVariantMember(node.expectNumberNode().getValue().intValue(), node);
        }

        @Override
        Node asNode() {
            return Node.from(value);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T getValue() {
            return (T) value;
        }
    }

// other variant classes 

// code for builder 

// code for provider
}
```

And pattern match can be used like :
``` java
UnionTrait unionTrait = shape.expectTrait("UnionTrait.class)
if (unionTrait instanceof UnionTrait.StringVaraiantMember) {
     // code
} else if (unionTrait instanceof UnionTrait.IntegerVariantMember) {
    // other code
}
```

