  const [count, setCount] = createSignal(0);
  return (() => {
    var _el$ = _tmpl$(), _el$1 = _el$.firstChild;
    _el$.$$click = () => setCount(count() + 1);
    _$insert(_el$, count(), _el$1);
    return _el$;
  })();
};
_$delegateEvents(["click"]);
```

